11	/**
12	 * 放射性药物服务 API 请求/响应载体。时刻字段请求与响应均为 ISO-8601 UTC 字符串。
13	 */
14	public final class RadioApiDtos {
15	
16	    private RadioApiDtos() {
17	    }
18	
19	    /** 活度计登记请求。 */
20	    public record RegisterCalibratorRequest(@NotBlank String code, @NotBlank String name) {
21	    }
22	
23	    /** 日检请求：requestId 幂等；偏差绝对值恰 5% 通过，超过 5% 当日禁用。 */
24	    public record DailyCheckRequest(
25	            @NotBlank String requestId,
26	            @NotNull Long calibratorId,
27	            @NotBlank String checkDate,
28	            @Positive double referenceActivityBq,
29	            @Positive double measuredActivityBq) {
30	
31	        public LocalDate parsedCheckDate() {
32	            return LocalDate.parse(checkDate);
33	        }
34	    }
35	
36	    /** 母液登记请求。referenceTime 为初始活度标定时刻（ISO-8601 UTC）。 */
37	    public record RegisterMotherLiquorRequest(
38	            @NotBlank String batchCode,
39	            @NotBlank String nuclideCode,
40	            @Positive double initialActivityBq,
41	            @NotBlank String referenceTime) {
42	
43	        public long referenceTimeEpoch() {
44	            return Instant.parse(referenceTime).getEpochSecond();
45	        }
46	    }
47	
48	    /** 处方登记请求。administrationTime 为给药时刻（ISO-8601 UTC）。 */
49	    public record RegisterPrescriptionRequest(
50	            @NotBlank String code,
51	            @NotBlank String nuclideCode,
52	            @Positive double prescribedActivityBq,
53	            @NotBlank String administrationTime) {
54	
55	        public long administrationTimeEpoch() {
56	            return Instant.parse(administrationTime).getEpochSecond();
57	        }
58	    }
59	
60	    /** 分装计算请求：requestId 幂等；与处方偏差恰 10% 合法，超过 10% 拒绝。 */
61	    public record CalculateRequest(
62	            @NotBlank String requestId,
63	            @NotNull Long motherLiquorId,
64	            @NotNull Long prescriptionId,
65	            @NotNull Long calibratorId) {
66	    }
67	
68	    /** 双人核对请求。 */
69	    public record CheckRequest(@NotBlank String checker) {
70	    }
71	
72	    /** 发药请求：requestId 幂等；measuredAt 为剩余活度测量时刻（ISO-8601 UTC）。 */
73	    public record DispenseRequest(
74	            @NotBlank String requestId,
75	            @NotNull Long dispensingId,
76	            @PositiveOrZero double remainingActivityBq,
77	            @NotBlank String measuredAt) {
78	
79	        public long measuredAtEpoch() {
80	            return Instant.parse(measuredAt).getEpochSecond();
81	        }
82	    }
83	
84	    /** 迟到测量数据请求。 */
85	    public record MeasurementRequest(@NotBlank String payload) {
86	    }
87	}
