53	                    "INSERT INTO calibrator_daily_check (request_id, fingerprint, calibrator_id, check_date,"
54	                            + " reference_activity_bq, measured_activity_bq, deviation_ratio, passed, created_at_epoch)"
55	                            + " VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
56	                    Statement.RETURN_GENERATED_KEYS);
57	            ps.setString(1, check.requestId());
58	            ps.setString(2, check.fingerprint());
59	            ps.setLong(3, check.calibratorId());
60	            ps.setDate(4, Date.valueOf(check.checkDate()));
61	            ps.setDouble(5, check.referenceActivityBq());
62	            ps.setDouble(6, check.measuredActivityBq());
63	            ps.setDouble(7, check.deviationRatio());
64	            ps.setBoolean(8, check.passed());
65	            ps.setLong(9, createdAtEpoch);
66	            return ps;
67	        }, keys);
68	        return keys.getKey().longValue();
69	    }
