76	    public Optional<DailyCheck> findDailyCheck(long calibratorId, LocalDate checkDate) {
77	        return jdbc.query("SELECT * FROM calibrator_daily_check WHERE calibrator_id = ? AND check_date = ?",
78	                this::mapDailyCheck, calibratorId, Date.valueOf(checkDate)).stream().findFirst();
79	    }
