1	package com.example.starter.radio.service;
2	
3	import static org.assertj.core.api.Assertions.assertThat;
4	import static org.assertj.core.api.Assertions.assertThatThrownBy;
5	
6	import java.time.Instant;
7	
8	import com.example.starter.radio.domain.DispensingStatus;
9	import com.example.starter.radio.model.Dispensing;
10	import com.example.starter.radio.model.MotherLiquor;
11	import com.example.starter.radio.model.Prescription;
12	import com.example.starter.radio.model.ReconciliationLedger;
13	import com.example.starter.radio.repository.MotherLiquorRepository;
14	import com.example.starter.radio.support.IntegrationTestBase;
15	import org.junit.jupiter.api.Test;
16	import org.springframework.beans.factory.annotation.Autowired;
17	
18	/**
19	 * 分装计算、双人核对与发药勾稽的 H2 集成测试。
20	 * 合成数据：SYN-1H 半衰期 3600s；母液 2200 Bq @ T0；给药时刻 T0+1h，衰变后恰 1100 Bq。
21	 */
22	class DispensingServiceTest extends IntegrationTestBase {
23	
24	    private static final long ADMIN_EPOCH = T0.getEpochSecond() + 3600L;
25	
26	    @Autowired
27	    private DispensingService dispensingService;
28	
29	    @Autowired
30	    private CalibratorService calibratorService;
31	
32	    @Autowired
33	    private RegistrationService registrationService;
34	
35	    @Autowired
36	    private MotherLiquorRepository motherLiquors;
37	
38	    @Test
39	    void decaysToAdministrationTimeAndExactlyTenPercentIsLegal() {
40	        Fixture f = newFixture(1000.0);
41	        Dispensing d = dispensingService.calculate(unique("REQ"), f.motherId, f.prescriptionId, f.calibratorId);
42	        // 2200 Bq 经 1 个半衰期推算至给药时刻恰为 1100 Bq；与处方 1000 Bq 偏差恰 10%，合法
43	        assertThat(d.dispensedActivityBq()).isEqualTo(1100.0);
44	        assertThat(d.deviationRatio()).isEqualTo(0.1);
45	        assertThat(d.status()).isEqualTo(DispensingStatus.CALCULATED);
46	    }
47	
48	    @Test
49	    void overTenPercentDeviationIsRejected() {
50	        Fixture f = newFixture(900.0);
51	        Dispensing d = dispensingService.calculate(unique("REQ"), f.motherId, f.prescriptionId, f.calibratorId);
52	        assertThat(d.status()).isEqualTo(DispensingStatus.REJECTED);
53	        assertThat(d.dispensedActivityBq()).isNull();
54	        assertThat(d.deviationRatio()).isGreaterThan(0.10);
55	    }
56	
57	    @Test
58	    void calculateIsIdempotentAndRejectsSameKeyDifferentParams() {
59	        Fixture f = newFixture(1000.0);
60	        String requestId = unique("REQ");
61	        Dispensing first = dispensingService.calculate(requestId, f.motherId, f.prescriptionId, f.calibratorId);
62	        Dispensing replay = dispensingService.calculate(requestId, f.motherId, f.prescriptionId, f.calibratorId);
63	        assertThat(replay.id()).isEqualTo(first.id());
64	
65	        Fixture other = newFixture(1000.0);
66	        assertThatThrownBy(() -> dispensingService.calculate(requestId, other.motherId,
67	                other.prescriptionId, other.calibratorId))
68	                .isInstanceOf(ConflictException.class);
69	    }
70	
71	    @Test
72	    void calibratorDisabledForTheDayAfterFailedCheck() {
73	        long calibratorId = registrationService.registerCalibrator(unique("CAL"), "合成活度计");
74	        calibratorService.dailyCheck(unique("REQ"), calibratorId, CHECK_DATE, 1000.0, 1051.0);
75	        MotherLiquor mother = registrationService.registerMotherLiquor(unique("ML"), "SYN-1H",
76	                2200.0, T0.getEpochSecond());
77	        Prescription prescription = registrationService.registerPrescription(unique("RX"), "SYN-1H",
78	                1000.0, ADMIN_EPOCH);
79	        assertThatThrownBy(() -> dispensingService.calculate(unique("REQ"), mother.id(),
80	                prescription.id(), calibratorId))
81	                .isInstanceOf(BusinessException.class)
82	                .hasMessageContaining("日检");
83	    }
84	
85	    @Test
86	    void dualCheckRequiresTwoDistinctCheckers() {
87	        Fixture f = newFixture(1000.0);
88	        Dispensing calculated = dispensingService.calculate(unique("REQ"), f.motherId,
89	                f.prescriptionId, f.calibratorId);
90	        Dispensing afterFirst = dispensingService.check(calculated.id(), "alice");
91	        assertThat(afterFirst.firstChecker()).isEqualTo("alice");
92	        assertThat(afterFirst.status()).isEqualTo(DispensingStatus.CALCULATED);
93	
94	        // 单人重复核对不生效
95	        assertThatThrownBy(() -> dispensingService.check(calculated.id(), "alice"))
96	                .isInstanceOf(ConflictException.class);
97	
98	        Dispensing afterSecond = dispensingService.check(calculated.id(), "bob");
99	        assertThat(afterSecond.secondChecker()).isEqualTo("bob");
100	        assertThat(afterSecond.status()).isEqualTo(DispensingStatus.CHECKED);
101	    }
102	
103	    @Test
104	    void dispenseBeforeDualCheckRejected() {
105	        Fixture f = newFixture(1000.0);
106	        Dispensing d = dispensingService.calculate(unique("REQ"), f.motherId, f.prescriptionId, f.calibratorId);
107	        assertThatThrownBy(() -> dispensingService.dispense(unique("REQ"), d.id(), 0.0, ADMIN_EPOCH))
108	                .isInstanceOf(BusinessException.class);
109	    }
110	
111	    @Test
112	    void dispenseReconcilesAndDeductsMotherLiquorAtomically() {
113	        Fixture f = newCheckedFixture();
114	        DispensingService.DispenseResult result = dispensingService.dispense(unique("REQ"),
115	                f.dispensingId, 0.0, ADMIN_EPOCH);
116	        assertThat(result.replayed()).isFalse();
117	        assertThat(result.dispensing().status()).isEqualTo(DispensingStatus.DISPENSED);
118	        // 勾稽：2200 = 1100(分装总量) + 0(剩余) + 1100(衰变残量)
119	        ReconciliationLedger ledger = result.ledger();
120	        assertThat(ledger.balanced()).isTrue();
121	        assertThat(ledger.initialActivityBq()).isEqualTo(2200.0);
122	        assertThat(ledger.dispensedTotalBq()).isEqualTo(1100.0);
123	        assertThat(ledger.remainingActivityBq()).isEqualTo(0.0);
124	        assertThat(ledger.decayResidualBq()).isEqualTo(1100.0);
125	        // 发药与扣减同事务：库存必须变化
126	        MotherLiquor mother = motherLiquors.findById(f.motherId).orElseThrow();
127	        assertThat(mother.remainingActivityBq()).isEqualTo(0.0);
128	        assertThat(mother.remainingTimeEpoch()).isEqualTo(ADMIN_EPOCH);
129	    }
130	
131	    @Test
132	    void unbalancedReconciliationRejectsAndKeepsInventoryUnchanged() {
133	        Fixture f = newCheckedFixture();
134	        assertThatThrownBy(() -> dispensingService.dispense(unique("REQ"), f.dispensingId, 500.0, ADMIN_EPOCH))
135	                .isInstanceOf(BusinessException.class)
136	                .hasMessageContaining("勾稽");
137	        // 事务回滚：母液剩余活度不变，批次仍为已核对
138	        MotherLiquor mother = motherLiquors.findById(f.motherId).orElseThrow();
139	        assertThat(mother.remainingActivityBq()).isEqualTo(2200.0);
140	        assertThat(jdbc.queryForObject("SELECT status FROM dispensing WHERE id = ?",
141	                String.class, f.dispensingId)).isEqualTo("CHECKED");
142	        assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM reconciliation_ledger",
143	                Integer.class)).isZero();
144	    }
145	
146	    @Test
147	    void dispenseReplayReturnsFirstResultAndTerminalRepeatSucceeds() {
148	        Fixture f = newCheckedFixture();
149	        String requestId = unique("REQ");
150	        DispensingService.DispenseResult first = dispensingService.dispense(requestId,
151	                f.dispensingId, 0.0, ADMIN_EPOCH);
152	        // 同键同参：返回首次结果，不重复扣减
153	        DispensingService.DispenseResult replay = dispensingService.dispense(requestId,
154	                f.dispensingId, 0.0, ADMIN_EPOCH);
155	        assertThat(replay.replayed()).isTrue();
156	        assertThat(replay.dispensing().dispensedAtEpoch()).isEqualTo(first.dispensing().dispensedAtEpoch());
157	        // 同键异参：409，且不重复扣减
158	        assertThatThrownBy(() -> dispensingService.dispense(requestId, f.dispensingId, 1.0, ADMIN_EPOCH))
159	                .isInstanceOf(ConflictException.class);
160	        // 终态重复完成：幂等成功
161	        DispensingService.DispenseResult repeat = dispensingService.dispense(unique("REQ"),
162	                f.dispensingId, 0.0, ADMIN_EPOCH);
163	        assertThat(repeat.replayed()).isTrue();
164	        assertThat(repeat.dispensing().status()).isEqualTo(DispensingStatus.DISPENSED);
165	        // 全程只扣减一次、台账只有一条
166	        MotherLiquor mother = motherLiquors.findById(f.motherId).orElseThrow();
167	        assertThat(mother.remainingActivityBq()).isEqualTo(0.0);
168	        assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM reconciliation_ledger WHERE dispensing_id = ?",
169	                Integer.class, f.dispensingId)).isEqualTo(1);
170	    }
171	
172	    @Test
173	    void lateMeasurementAfterCompletionOnlyRecordsLateEvent() {
174	        Fixture f = newCheckedFixture();
175	        dispensingService.dispense(unique("REQ"), f.dispensingId, 0.0, ADMIN_EPOCH);
176	        String result = dispensingService.recordMeasurement(f.dispensingId, "late-reading=0.0Bq");
177	        assertThat(result).isEqualTo("LATE_RECORDED");
178	        assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM late_event WHERE dispensing_id = ?",
179	                Integer.class, f.dispensingId)).isEqualTo(1);
180	        assertThat(jdbc.queryForObject("SELECT status FROM dispensing WHERE id = ?",
181	                String.class, f.dispensingId)).isEqualTo("DISPENSED");
182	    }
183	
184	    @Test
185	    void reconciliationLedgerIsRecomputable() {
186	        Fixture f = newCheckedFixture();
187	        dispensingService.dispense(unique("REQ"), f.dispensingId, 0.0, ADMIN_EPOCH);
188	        ReconciliationLedger recomputed = dispensingService.recompute(f.dispensingId);
189	        assertThat(recomputed.balanced()).isTrue();
190	        assertThat(recomputed.initialActivityBq()).isEqualTo(2200.0);
191	        assertThat(recomputed.dispensedTotalBq()).isEqualTo(1100.0);
192	        assertThat(recomputed.remainingActivityBq()).isEqualTo(0.0);
193	        assertThat(recomputed.decayResidualBq()).isEqualTo(1100.0);
194	    }
195	
196	    /** 构造已完成双人核对的批次夹具。 */
197	    private Fixture newCheckedFixture() {
198	        Fixture f = newFixture(1000.0);
199	        Dispensing d = dispensingService.calculate(unique("REQ"), f.motherId, f.prescriptionId, f.calibratorId);
200	        dispensingService.check(d.id(), "alice");
201	        dispensingService.check(d.id(), "bob");
202	        return new Fixture(f.motherId, f.prescriptionId, f.calibratorId, d.id());
