46	                        + "\"referenceTime\":\"2026-09-26T00:00:00Z\"}");
47	        long prescriptionId = postAndGetId("/api/prescriptions",
48	                "{\"code\":\"RX-API-1\",\"nuclideCode\":\"SYN-1H\",\"prescribedActivityBq\":1000.0,"
