                .andExpect(status().isUnprocessableEntity());
        mvc.perform(get("/api/dispensings/changes/{id}", changeId))
                .andExpect(jsonPath("$.status").value("REJECTED"));
    }

    @Test
    void changeErrorSemanticsOverHttp() throws Exception {
