                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("PENDING"));
        long changeId = changeService.changes(dispensingId).get(0).id();
        // 作废
        mvc.perform(post("/api/dispensings/changes/{id}/cancel", changeId))
